import{_ as t,c as r,o as a,ae as o}from"./chunks/framework.BtEkjhVd.js";const p=JSON.parse('{"title":"Project Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),n={name:"architecture.md"};function i(s,e,l,d,c,h){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="project-architecture" tabindex="-1">Project Architecture <a class="header-anchor" href="#project-architecture" aria-label="Permalink to &quot;Project Architecture&quot;">​</a></h1><p>This page provides a high-level overview of the fAIr platform’s architecture, including its main components, data flow, and technology stack.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>fAIr is a modular, containerized platform designed for AI-assisted mapping. It consists of several services that work together to process imagery, train AI models, and assist users in mapping tasks.</p><hr><h2 id="main-components" tabindex="-1">Main Components <a class="header-anchor" href="#main-components" aria-label="Permalink to &quot;Main Components&quot;">​</a></h2><ul><li><p><strong>Frontend</strong><br> Built with React and TypeScript, the frontend provides an intuitive web interface for users to manage datasets, train models, and perform mapping tasks.</p></li><li><p><strong>Backend API</strong><br> Powered by Django (Python), the backend exposes REST APIs for user management, dataset handling, model training, and prediction services.</p></li><li><p><strong>AI/ML Workers</strong><br> Use TensorFlow and PyTorch for training and running AI models. Workers are managed via Celery for distributed task processing.</p></li><li><p><strong>Database</strong><br> PostgreSQL with PostGIS extension stores user data, project metadata, and geospatial information.</p></li><li><p><strong>Redis</strong><br> Used as a message broker for Celery task queues.</p></li><li><p><strong>Flower</strong><br> Provides a web UI for monitoring Celery tasks and workers.</p></li><li><p><strong>Developer Documentation</strong><br> Served via VitePress. Run <code>npm run docs:dev</code> and visit the port shown in your terminal.</p></li></ul><hr><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><ol><li><strong>User uploads or selects imagery</strong> (e.g., from OpenAerialMap).</li><li><strong>Frontend sends requests</strong> to the backend API to create datasets and manage projects.</li><li><strong>Backend schedules AI tasks</strong> (training, prediction) via Celery.</li><li><strong>AI/ML workers</strong> process imagery and labels, train models, and generate predictions.</li><li><strong>Results are stored</strong> in the database and made available to the frontend for review and editing.</li><li><strong>Users review, edit, and validate predictions</strong> before exporting or uploading to OSM.</li></ol><hr><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><ul><li><strong>Frontend:</strong> React, TypeScript, Vite</li><li><strong>Backend:</strong> Django, Django REST Framework</li><li><strong>AI/ML:</strong> TensorFlow, PyTorch</li><li><strong>Task Queue:</strong> Celery, Redis</li><li><strong>Database:</strong> PostgreSQL, PostGIS</li><li><strong>Containerization:</strong> Docker, Docker Compose</li><li><strong>Documentation:</strong> MkDocs Material</li></ul><hr><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>All services are containerized and orchestrated using Docker Compose.<br> See <a href="./Docker-installation.html">Docker Installation (Linux/Mac)</a> or <a href="./Docker-install-windows.html">Docker Installation (Windows)</a> for setup instructions.</p><hr><h2 id="extending-the-platform" tabindex="-1">Extending the Platform <a class="header-anchor" href="#extending-the-platform" aria-label="Permalink to &quot;Extending the Platform&quot;">​</a></h2><ul><li><strong>Add new AI models:</strong> Integrate custom models by extending the AI worker codebase.</li><li><strong>API integrations:</strong> Use the REST API to connect with external tools or automate workflows.</li><li><strong>Frontend plugins:</strong> Enhance the user interface with new features or visualization tools.</li></ul><hr><h2 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to &quot;Diagram&quot;">​</a></h2><blockquote><p><em>A system architecture diagram can be added here for visual reference (e.g., using <a href="https://diagrams.net" target="_blank" rel="noreferrer">diagrams.net</a> or Mermaid).</em></p></blockquote><hr><p>For more details, see the <a href="./contributing.html">contributing guide</a> or open an issue on <a href="https://github.com/hotosm/fAIr/issues" target="_blank" rel="noreferrer">GitHub</a>.</p>',25)]))}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
